// Прод, только чтение: все категории из sitemap, сырой HTML через request API, параллельно по 8.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, rootHtml, seoBody, links, jsonLd, nodesOfType, categoryPath, pool } from './ssr-seo.helpers';

test.describe('SSR и SEO публичных страниц — SSR-контент', () => {
  test('Категории из sitemap: в сыром HTML SSR-блок с карточками и JSON-LD ItemList с numberOfItems #b3dc2e @desktop @prod-safe', async ({ request }) => {
    test.setTimeout(5 * 60_000);
    const sm = await readSitemap(request);
    expect(sm.categories.length, 'категории в sitemap').toBeGreaterThan(0);

    const rows = await pool(
      sm.categories,
      async (cat) => {
        const problems: string[] = [];
        const { status, html } = await rawHtml(request, categoryPath(cat));
        if (status !== 200) return { cat, problems: [`HTTP ${status}`] };
        const seo = seoBody(rootHtml(html) ?? '');
        if (!seo) problems.push('нет [data-seo-body]');
        const ld = jsonLd(html);
        if (ld.errors.length) problems.push(`JSON-LD не парсится: ${ld.errors.join('; ')}`);
        const lists = nodesOfType(ld, 'ItemList');
        if (lists.length !== 1) {
          problems.push(`ItemList: ${lists.length}`);
        } else {
          const n = Number(lists[0]['numberOfItems']);
          if (!Number.isInteger(n) || n < 0) problems.push(`numberOfItems=${lists[0]['numberOfItems']}`);
          const cards = seo ? links(seo.html).filter((l) => l.href.includes('/businessdetail?id=')) : [];
          if (n > 0 && cards.length === 0) problems.push(`numberOfItems=${n}, а карточек в SSR-блоке нет`);
        }
        return { cat, problems };
      },
      (cat, e) => ({ cat, problems: [`ошибка запроса: ${e.message.split('\n')[0]}`] }),
    );

    const bad = rows.filter((r) => r.problems.length);
    expect(bad.map((r) => `${r.cat}: ${r.problems.join('; ')}`), `нарушителей ${bad.length}/${rows.length}`).toEqual([]);
  });
});
